import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { SAMPLE_VIDEO } from '../data';

export default function Login({ onLogin }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [role, setRole] = useState('student'); // student or staff
  const [error, setError] = useState('');

  const handleChange = e =>
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));

  async function handleSubmit(e) {
    e.preventDefault();
    setError('');

    try {
      // 🔗 Call backend API (unchanged)
      const res = await fetch('http://localhost:5000/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, role }),
      });

      const data = await res.json();

      if (res.ok && data.token) {
        localStorage.setItem('token', data.token);
        onLogin(data.user);
        navigate('/dashboard');
      } else {
        setError(data.message || 'Invalid email or password');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('Something went wrong. Please try again.');
    }
  }

  const bgColor = role === 'student' ? '#e3f2fd' : '#e8f5e9';
  const themeColor = role === 'student' ? '#1976d2' : '#2e7d32';

  return (
    <div
      className="auth-page"
      style={{
        background: bgColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        transition: '0.3s ease',
      }}
    >
      <div className="auth-card" style={{
        background: 'white',
        borderRadius: '16px',
        padding: '40px',
        boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
        width: '380px'
      }}>
        <h1 style={{ color: themeColor, textAlign: 'center' }}>Welcome to Nexora</h1>

        <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', margin: '12px 0' }}>
          <button
            onClick={() => setRole('student')}
            style={{
              background: role === 'student' ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '6px 12px',
              cursor: 'pointer',
            }}
          >
            Student
          </button>
          <button
            onClick={() => setRole('staff')}
            style={{
              background: role === 'staff' ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '6px 12px',
              cursor: 'pointer',
            }}
          >
            Staff
          </button>
        </div>

        <form className="form" onSubmit={handleSubmit}>
          <input
            className="input"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            required
          />
          <input
            className="input"
            name="password"
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            required
          />
          <button
            className="btn btn-primary"
            type="submit"
            style={{
              background: themeColor,
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '10px',
              width: '100%',
              marginTop: '10px',
              cursor: 'pointer',
            }}
          >
            Login
          </button>
          {error && (
            <p style={{ color: 'red', marginTop: '8px' }}>{error}</p>
          )}
          <div style={{ marginTop: 12, textAlign: 'center' }}>
            <span>New? </span>
            <Link to="/signup" style={{ color: themeColor }}>
              Create account
            </Link>
          </div>
        </form>
      </div>
    </div>
  );
}
